Step.StepText:
Set Variable [ $resultPrices; Value:Let ( [
  // park real returns on Char(11) so only Char(30) breaks rows
  ~ok = Left ( $raw ; 1 ) <> "?" and not IsEmpty ( $raw ) ;
  ~rows = Substitute ( Substitute ( $raw ; ¶ ; Char ( 11 ) ) ; Char ( 30 ) ; ¶ ) ;
  ~n = If ( ~ok ; ValueCount ( ~rows ) ; 0 )
] ;
While (
  [ ~i = 1 ; ~out = "[]" ] ;
  ~i <= ~n ;
  [
    ~r = Substitute ( GetValue ( ~rows ; ~i ) ; Char ( 31 ) ; ¶ ) ;
    ~p = "[" & ( ~i - 1 ) & "]" ;
    ~out = JSONSetElement ( ~out ;
      [ ~p & ".id" ; GetValue ( ~r ; 1 ) ; JSONString ] ;
      [ ~p & ".sku" ; Substitute ( GetValue ( ~r ; 2 ) ; Char ( 11 ) ; ¶ ) ; JSONString ] ;
      [ ~p & ".tier" ; GetValue ( ~r ; 3 ) ; JSONString ] ;
      [ ~p & ".price" ; GetValue ( ~r ; 4 ) ; JSONString ] ;
      [ ~p & ".description" ; Substitute ( GetValue ( ~r ; 5 ) ; Char ( 11 ) ; ¶ ) ; JSONString ] ;
      [ ~p & ".modified" ; GetValue ( ~r ; 6 ) ; JSONString ] ;
      [ ~p & ".modifiedBy" ; GetValue ( ~r ; 7 ) ; JSONString ]
    ) ;
    ~i = ~i + 1
  ] ;
  ~out
) ) ]

