    ~price = Substitute ( Trim ( JSONGetElement ( $rows ; ~p & ".price" ) ) ; [ "$" ; "" ] ; [ "," ; "" ] ) ;
    ~key = Upper ( ~sku ) & "|" & ~tier ;
    ~dup = GetAsNumber ( ExecuteSQL ( "select count(*) from \"FCBPrice\" where upper(\"SKU\") = ? and upper(\"Tier\") = ? and cast(\"__ID\" as varchar) <> ?" ; "" ; "" ; Upper ( ~sku ) ; ~tier ; If ( IsEmpty ( ~id ) ; "0" ; ~id ) ) ) ;
    ~label = If ( IsEmpty ( ~sku ) ; "Row " & ( ~i + 1 ) ; ~sku & " " & ~tier ) ;
    ~err = List ( ~err ;
      Case (
        IsEmpty ( ~sku ) ; ~label & ": SKU is required." ;
        IsEmpty ( ~tier ) ; ~label & ": tier is required." ;
        IsEmpty ( ~price ) or Filter ( ~price ; "0123456789." ) <> ~price or PatternCount ( ~price ; "." ) > 1 ; ~label & ": price must be a number." ;
        ~dup > 0 ; ~label & ": already in the price table." ;
        PatternCount ( ¶ & ~seen & ¶ ; ¶ & ~key & ¶ ) ; ~label & ": listed twice." ;
        ""
      )
    ) ;
    ~seen = List ( ~seen ; ~key ) ;
    ~i = ~i + 1
  ] ;
  ~err
)

